package kr.pdfmemorynotes;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.graphics.*;import com.google.mlkit.vision.text.*;import com.google.mlkit.vision.text.korean.*;import com.google.mlkit.vision.common.InputImage;import com.google.android.gms.tasks.Tasks;import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
public final class ImportService extends Service {
 static volatile boolean running;static volatile String progress="";private volatile boolean cancelled;private ExecutorService executor;private Store store;
 public void onCreate(){super.onCreate();store=new Store(this);executor=Executors.newSingleThreadExecutor();getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("convert","PDF 변환",NotificationManager.IMPORTANCE_LOW));}
 Notification notification(String text){Intent i=new Intent(this,ImportService.class).setAction("cancel");PendingIntent stop=PendingIntent.getService(this,2,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"convert").setSmallIcon(android.R.drawable.ic_menu_upload).setContentTitle("PDF 암기노트").setContentText(text).setOngoing(true).addAction(new Notification.Action.Builder(null,"일시 중지",stop).build()).build();}
 void update(String s){progress=s;getSystemService(NotificationManager.class).notify(1,notification(s));}
 public int onStartCommand(Intent i,int flags,int id){if(i==null){stopSelf();return START_NOT_STICKY;}if("cancel".equals(i.getAction())){cancelled=true;return START_NOT_STICKY;}if(running)return START_NOT_STICKY;running=true;cancelled=false;startForeground(1,notification("준비 중"));Uri uri=i.getData();long doc=i.getLongExtra("doc",-1);executor.execute(()->{long current=doc;try{if(uri!=null)current=importFile(uri);if(current>=0&&!cancelled)convert(current);}catch(Exception e){if(current>=0)store.state(current,"중단됨",message(e));progress=message(e);}finally{running=false;stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}});return START_NOT_STICKY;}
 static String message(Exception e){String s=e.getMessage();return "처리를 완료하지 못했습니다. 이어서 변환하거나 다른 PDF를 선택해 주세요.\n"+(s==null?e.getClass().getSimpleName():s);}
 void check()throws IOException{if(cancelled||Thread.currentThread().isInterrupted())throw new IOException("일시 중지되었습니다. 저장된 페이지부터 이어서 처리할 수 있습니다.");}
 long importFile(Uri uri)throws Exception{File dir=new File(getFilesDir(),"pdfs");if(!dir.exists()&&!dir.mkdirs())throw new IOException("저장 폴더를 만들 수 없습니다");String name="PDF 문서";long size=-1;try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){name=c.getString(0);if(!c.isNull(1))size=c.getLong(1);}}if(size>0&&dir.getUsableSpace()<size+32L*1024*1024)throw new IOException("PDF를 보관할 저장 공간이 부족합니다");File temp=new File(dir,UUID.randomUUID()+".part");MessageDigest digest=MessageDigest.getInstance("SHA-256");long total=0;try{try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException("PDF를 열 수 없습니다");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){check();out.write(buffer,0,n);digest.update(buffer,0,n);total+=n;if(total%(4*1024*1024)<65536){if(dir.getUsableSpace()<16L*1024*1024)throw new IOException("저장 공간이 부족합니다");update("PDF 보관 중 · "+total/1048576+"MB"+(size>0?" / "+size/1048576+"MB":""));}}out.getFD().sync();}check();int count=PdfPages.count(temp);if(count<1)throw new IOException("페이지가 없는 PDF입니다");StringBuilder hex=new StringBuilder();for(byte b:digest.digest())hex.append(String.format(java.util.Locale.ROOT,"%02x",b));File finalFile=new File(dir,hex+".pdf");if(finalFile.exists())temp.delete();else if(!temp.renameTo(finalFile))throw new IOException("PDF 보관을 마치지 못했습니다");return store.doc(name,finalFile.getAbsolutePath(),count);}finally{if(temp.exists())temp.delete();}}
 void convert(long doc)throws Exception{JSONObject d=store.get(doc);if(d==null)throw new IOException("문서를 찾을 수 없습니다");int pages=d.getInt("pages"),done=d.getInt("done");File file=new File(d.getString("path"));TextRecognizer recognizer=TextRecognition.getClient(new KoreanTextRecognizerOptions.Builder().build());store.state(doc,"변환 중","");try{int[] next={1};for(int old=0;old<done;old++)for(Splitter.Line line:store.lines(doc,old))if(line.blue&&line.text.trim().matches("[0-9]{2}"))next[0]++;for(int page=done;page<pages;page++){check();update("글자 인식 · "+(page+1)+" / "+pages+"쪽");Bitmap bitmap=PdfPages.render(file,page,1600);try{Text result=Tasks.await(recognizer.process(InputImage.fromBitmap(bitmap,0)));check();List<Splitter.Line> lines=new ArrayList<>();for(Text.TextBlock block:result.getTextBlocks())for(Text.Line line:block.getLines()){Rect r=line.getBoundingBox();if(r!=null)lines.add(new Splitter.Line(page,(float)r.left/bitmap.getWidth(),(float)r.top/bitmap.getHeight(),(float)r.right/bitmap.getWidth(),(float)r.bottom/bitmap.getHeight(),line.getText(),PdfPages.blue(bitmap,r)));}MarkerDetector.Marks marks=MarkerDetector.detect(bitmap::getPixel,bitmap.getWidth(),bitmap.getHeight());store.page(doc,page,MarkerDetector.merge(lines,marks,page,next));}finally{bitmap.recycle();}}store.rebuild(doc,pages);store.state(doc,"완료","");update("변환을 마쳤습니다");}catch(Exception e){int processed=store.get(doc).optInt("done");if(processed>0)store.rebuild(doc,processed);store.state(doc,cancelled?"일시 중지":"중단됨",cancelled?"":message(e));throw e;}finally{recognizer.close();}}
 @Override public void onTimeout(int startId,int type){cancelled=true;stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 public void onDestroy(){cancelled=true;if(executor!=null)executor.shutdown();super.onDestroy();}public IBinder onBind(Intent i){return null;}
}
